"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[7152],{93071:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"WeaponServer","desc":"Authoritative weapon server. Plan 1 handles `ReqMeleeSwing`: it infers the\\nweapon from the requester\'s equipped Tool, gates the swing on the server-side\\ncooldown (`WeaponState`), re-runs the melee hitbox from the server\'s\\ncharacter CFrame, and routes damage through `CombatService`. Broadcasts\\n`WeaponImpact` per hit so all clients render impact FX. Never trusts client\\naim or client-claimed hits.\\n\\nPlan 2 adds authoritative hitscan fire (`ReqFireWeapon`), authoritative\\nreload (`ReqReloadWeapon`), and ammo initialisation on gun equip\\n(`WeaponMagSync` pushed to the owning client immediately; the shared\\nammo pool is owned by `AmmoManager` and synced via `AmmoPoolSync`).\\n\\nPlan 3 adds server-side rocket (projectile) cast via FastCast2. Throwable\\nweapons (grenade fuse + C4 manual) are handled via `ReqThrowProjectile` and\\n`ReqDetonate`.\\n\\nHitscan and melee are lag-compensated: `ReqFireWeapon`/`ReqMeleeSwing`\\ncarry the client\'s Chrono render time and NPC hit tests run through\\n`LagCompensation` (rewound to that time, clamped server-side).","realm":["Server"],"source":{"line":26,"path":"src/ServerScriptService/WeaponServer.server.luau"}}')}}]);